// src/components/FaceRecognition.jsx
import React, { useEffect, useRef, useState } from "react";
import Webcam from "react-webcam";
import { useLocation, useNavigate } from "react-router-dom";
import "./CSS/FaceRecognition.css";

const FaceRecognition = () => {
  const webcamRef = useRef(null);
  const navigate = useNavigate();
  const { state } = useLocation();
  const email = state?.email;

  const [status, setStatus] = useState("Starting webcam...");

  const videoConstraints = { width: 300, height: 300, facingMode: "user" };

  useEffect(() => {
    let cancelled = false;

    const run = async () => {
      if (!email) {
        alert("Email not provided for verification.");
        setStatus("Missing email.");
        return;
      }

      setStatus("Capturing face...");

      let imageSrc = null;
      for (let i = 0; i < 20 && !cancelled; i++) {
        await new Promise((r) => setTimeout(r, 200));
        imageSrc = webcamRef.current?.getScreenshot();
        if (imageSrc) break;
      }

      if (cancelled || !imageSrc) {
        alert("Could not capture face from webcam. Please refresh and try again.");
        setStatus("Capture failed.");
        return;
      }

      try {
        setStatus("Verifying face...");
        const res = await fetch("http://127.0.0.1:5000/verify-face", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email, image: imageSrc }),
        });

        const json = await res.json();

        if (json.success) {
          alert("Face verified successfully!");
          setStatus("Verified. Redirecting...");
          navigate("/dashboard");
        } else {
          alert("Face verification failed.");
          setStatus("Face verification failed.");
        }
      } catch (err) {
        console.error("[FaceRecognition] Error:", err);
        alert("Error verifying face. Please try again.");
        setStatus("Verification error.");
      }
    };

    run();
    return () => { cancelled = true; };
  }, [email, navigate]);

  return (
    <div className="face-container">
      <div className="face-box">
        <h2>Face Recognition</h2>
        <p className="face-status">{status}</p>

        <Webcam
          ref={webcamRef}
          audio={false}
          width={300}
          height={300}
          screenshotFormat="image/png"
          videoConstraints={videoConstraints}
          className="webcam"
        />
      </div>
    </div>
  );
};

export default FaceRecognition;
